SELECT

FROM debt_management
WHERE deleted = 0
AND debt_no = #{debtNo}

    AND id != #{excludeId}

LIMIT 1

SELECT

FROM debt_management

    deleted = 0

        AND project_id = #{param.projectId}


        AND debt_type = #{param.debtType}


        AND debt_no LIKE CONCAT('%', #{param.debtNo}, '%')


        AND debtor_name LIKE CONCAT('%', #{param.debtorName}, '%')


        AND debt_status = #{param.debtStatus}


        AND legal_status = #{param.legalStatus}


        AND responsible_person_id = #{param.responsiblePersonId}


        AND debt_date >= #{param.debtDateStart}


        AND debt_date <= #{param.debtDateEnd}


        AND debt_amount >= #{param.debtAmountMin}


        AND debt_amount <= #{param.debtAmountMax}


ORDER BY debt_status ASC, collection_difficulty DESC, debt_amount DESC, create_time DESC

SELECT COUNT(*) as totalDebts, SUM(debt_amount) as totalDebtAmount, SUM(collected_amount) as totalRecoveryAmount, SUM(debt_amount - IFNULL(collected_amount, 0)) as totalOutstandingAmount, SUM(CASE WHEN debt_type = 1 THEN 1 ELSE 0 END) as accountsReceivable, SUM(CASE WHEN debt_type = 2 THEN 1 ELSE 0 END) as contractDebts, SUM(CASE WHEN debt_type = 3 THEN 1 ELSE 0 END) as otherDebts, SUM(CASE WHEN debt_status = 1 THEN 1 ELSE 0 END) as activeDebts, SUM(CASE WHEN debt_status = 2 THEN 1 ELSE 0 END) as partiallyRecovered, SUM(CASE WHEN debt_status = 3 THEN 1 ELSE 0 END) as fullyRecovered, SUM(CASE WHEN debt_status = 4 THEN 1 ELSE 0 END) as writeOffDebts, SUM(CASE WHEN collection_difficulty = 1 THEN 1 ELSE 0 END) as easyCollection, SUM(CASE WHEN collection_difficulty = 2 THEN 1 ELSE 0 END) as normalCollection, SUM(CASE WHEN collection_difficulty = 3 THEN 1 ELSE 0 END) as difficultCollection, SUM(CASE WHEN collection_difficulty = 4 THEN 1 ELSE 0 END) as veryDifficultCollection, SUM(CASE WHEN legal_status = 1 THEN 1 ELSE 0 END) as noLegalAction, SUM(CASE WHEN legal_status = 2 THEN 1 ELSE 0 END) as legalActionPlanned, SUM(CASE WHEN legal_status = 3 THEN 1 ELSE 0 END) as legalActionInProgress, SUM(CASE WHEN legal_status = 4 THEN 1 ELSE 0 END) as legalActionCompleted, AVG(CASE WHEN debt_amount > 0 THEN (IFNULL(collected_amount, 0) / debt_amount) * 100 ELSE 0 END) as avgRecoveryRate FROM debt_management
deleted = 0
AND project_id = #{projectId}

SELECT debt_type, COUNT(*) as count, SUM(debt_amount) as totalAmount, SUM(collected_amount) as totalRecovery, AVG(CASE WHEN debt_amount > 0 THEN (IFNULL(collected_amount, 0) / debt_amount) * 100 ELSE 0 END) as avgRecoveryRate FROM debt_management
deleted = 0
AND project_id = #{projectId}
AND debt_date >= #{startDate}
AND debt_date <= #{endDate}
GROUP BY debt_type ORDER BY totalAmount DESC

SELECT DATE_FORMAT(debt_date, '%Y-%m') as month, COUNT(*) as totalCount, SUM(debt_amount) as totalAmount, SUM(collected_amount) as totalRecovery, AVG(CASE WHEN debt_amount > 0 THEN (IFNULL(collected_amount, 0) / debt_amount) * 100 ELSE 0 END) as avgRecoveryRate FROM debt_management
deleted = 0
AND project_id = #{projectId}
AND debt_date >= #{startDate}
AND debt_date <= #{endDate}
GROUP BY DATE_FORMAT(debt_date, '%Y-%m') ORDER BY month DESC LIMIT 12

